`README.md` lines 1-100:
```
# CMatrix

Matrix-like effect in your terminal

## Overview

CMatrix is based on the screensaver from The Matrix website. It shows text
flying in and out in a terminal like as seen in "The Matrix" movie. It can
scroll lines all at the same rate or asynchronously and at a user-defined
speed.

## Usage

Run CMatrix with the following command:
```sh
cmatrix
```

Run with different arguments to get different effects:
```sh
cmatrix [-abBflohnsmVx] [-u update] [-C color]
```

### Command-line Options

- `-a` - Asynchronous scroll
- `-b` - Bold characters on
- `-B` - All bold characters (overrides -b)
- `-f` - Force the linux $TERM type to be on
- `-l` - Linux mode (sets "matrix.fnt" font in console)
- `-o` - Use old-style scrolling
- `-c` - Only print the shadows of letters
- `-L` - Locks cmatrix, unable to quit
- `-h, -?` - Print usage and exit
- `-r` - "Rainbow" mode, rainbow colored characters
- `-k` - Every characters change
- `-n` - No bold characters (overrides -b and -B)
- `-s` - "Screensaver" mode, exits on first keystroke
- `-m` - "Lambda" mode, every character becomes a lambda
- `-x` - X window mode
- `-V` - Print version information and exit
- `-u delay` - Screen update delay 0-9, default 4
- `-C color` - Use this color for matrix (default green). Valid colors are green, red, blue, white, yellow, cyan, magenta and black.
- `-M message` - Add a message in the center of cmatrix
- `-t tty` - Set tty to use
```

`cmatrix.c` lines 1-280:
```
/*
 * CMatrix - A Matrix-like terminal effect
 * Based on the screensaver from The Matrix website
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <ncurses.h>
#include <termios.h>
#include <signal.h>

#define VERSION "1.0"
#define MAX_COLS 256
#define MAX_ROWS 256
#define MAX_LINES 256
#define MAX_MESSAGE_LEN 100

/* Global variables */
static int async_scroll = 0;
static int bold_chars = 0;
static int all_bold = 0;
static int no_bold = 0;
static int linux_mode = 0;
static int old_style = 0;
static int shadow_mode = 0;
static int lock_mode = 0;
static int screensaver_mode = 0;
static int x_window_mode = 0;
static int rainbow_mode = 0;
static int lambda_mode = 0;
static int chars_change = 0;
static int tty_set = 0;
static int use_japanese = 0;
static int use_message = 0;
static int message_set = 0;
static char message[MAX_MESSAGE_LEN] = "";
static int update_delay = 4;
static int color = 1;  /* 1 = green, 2 = red, 3 = blue, 4 = white, 5 = yellow, 6 = cyan, 7 = magenta, 8 = black */
static int tty_fd = -1;
static struct termios orig_termios;
static int running = 1;
static int async_toggle = 0;

/* Character sets */
static const char *ascii_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-=[]{}|;':\",./<>?";
static const char *katakana_chars = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッン";
static const char *katakana_chars2 = "ン";
static const char *katakana_full = "アァカサタナハマヤャラワガザダバパイィキシチニヒミリヰギジヂビピウゥクスツヌフムユュルグズブヅプエェケセテネヘメレヱゲゼデベペオォコソトノホモヨョロヲゴゾドボポヴッンン";

/* Color definitions */
static int get_color_attr(int c) {
    switch (c) {
        case 1: return COLOR_GREEN;  /* Default */
        case 2: return COLOR_RED;
        case 3: return COLOR_BLUE;
        case 4: return COLOR_WHITE;
        case 5: return COLOR_YELLOW;
        case 6: return COLOR_CYAN;
        case 7: return COLOR_MAGENTA;
        case 8: return COLOR_BLACK;
        default: return COLOR_GREEN;
    }
}

static int get_color_attr_rainbow(int c) {
    static int hue = 0;
    hue = (hue + 1) % 16;
    int fg = 0, bg = 0;
    switch (hue) {
        case 0: fg = COLOR_RED; break;
        case 1: fg = COLOR_GREEN; break;
        case 2: fg = COLOR_YELLOW; break;
        case 3: fg = COLOR_BLUE; break;
        case 4: fg = COLOR_MAGENTA; break;
        case 5: fg = COLOR_CYAN; break;
        case 6: fg = COLOR_WHITE; break;
        case 7: fg = COLOR_BLACK; break;
        default: fg = COLOR_GREEN;
    }
    return fg;
}

/* Print usage */
static void print_usage(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green).\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

/* Print version */
static void print_version(void) {
    printf("CMatrix version %s\n", VERSION);
}

/* Parse color argument */
static int parse_color(const char *color_str) {
    if (strcasecmp(color_str, "green") == 0) return 1;
    if (strcasecmp(color_str, "red") == 0) return 2;
    if (strcasecmp(color_str, "blue") == 0) return 3;
    if (strcasecmp(color_str, "white") == 0) return 4;
    if (strcasecmp(color_str, "yellow") == 0) return 5;
    if (strcasecmp(color_str, "cyan") == 0) return 6;
    if (strcasecmp(color_str, "magenta") == 0) return 7;
    if (strcasecmp(color_str, "black") == 0) return 8;
    return 1;  /* Default green */
}

/* Get character set based on mode */
static const char *get_char_set(void) {
    if (use_japanese) {
        return katakana_full;
    }
    return ascii_chars;
}

/* Initialize terminal */
static void init_term(void) {
    struct termios raw;

    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        return;
    }

    raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_iflag &= ~(IXON);
    raw.c_oflag &= 0;
    raw.c_cflag |= (CS8);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;

    if (tty_set) {
        tty_fd = open(tty, O_RDWR);
        if (tty_fd >= 0) {
            if (tcsetattr(tty_fd, TCSANOW, &raw) != 0) {
                close(tty_fd);
                tty_fd = -1;
            }
        }
    } else {
        if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
            return;
        }
    }

    cbreak();
    noecho();
    curs_set(0);
    keypad(stdscr, TRUE);
    nodelay(stdscr, TRUE);
}

/* Restore terminal */
static void restore_term(void) {
    if (tty_fd >= 0) {
        tcsetattr(tty_fd, TCSANOW, &orig_termios);
        close(tty_fd);
        tty_fd = -1;
    } else {
        tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
    }
    curs_set(1);
}

/* Draw the matrix rain */
static void draw_matrix(void) {
    int i, j, x, y, col, row;
    int max_y, max_x;
    int char_set_len;
    const char *char_set;
    int attr;
    int random_val;

    max_y = getmaxy(stdscr);
    max_x = getmaxx(stdscr);
    char_set = get_char_set();
    char_set_len = strlen(char_set);

    /* Clear screen */
    clear();

    /* Draw matrix rain */
    for (i = 0; i < MAX_LINES; i++) {
        int y = i % max_y;
        int x = (i * 10) % max_x;

        /* Get random character */
        random_val = rand() % char_set_len;
        char c = char_set[random_val];

        /* Determine color */
        if (rainbow_mode) {
            attr = get_color_attr_rainbow(i);
        } else {
            attr = get_color_attr(color);
        }

        /* Apply bold if needed */
        if (all_bold || (bold_chars && (rand() % 100 < 50))) {
            attr |= A_BOLD;
        } else if (no_bold) {
            attr &= ~A_BOLD;
        }

        /* Print character */
        if (shadow_mode) {
            mvaddch(y, x, ' ');
        } else {
            mvaddch(y, x, c);
        }
        mvaddch(y, x + 1, ' ');
    }

    /* Refresh screen */
    refresh();
}

/* Handle keystrokes */
static void handle_key(void) {
    int ch;

    ch = getch();

    if (ch == 'q' || ch == 'Q') {
        running = 0;
    } else if (ch == 'a' || ch == 'A') {
        async_scroll = !async_scroll;
        async_toggle = 1;
    } else if (ch == 'b' || ch == 'B') {
        bold_chars = !bold_chars;
    } else if (ch == 'n' || ch == 'N') {
        no_bold = !no_bold;
    } else if (ch >= '0' && ch <= '9') {
        update_delay = ch - '0';
    } else if (ch == '!') {
        color = 2;  /* red */
    } else if (ch == '@') {
        color = 1;  /* green */
    } else if (ch == '#') {
        color = 5;  /* yellow */
    } else if (ch == '$') {
        color = 3;  /* blue */
    } else if (ch == '%') {
        color = 7;  /* magenta */
    } else if (ch == '^') {
        color = 6;  /* cyan */
    } else if (ch == '&') {
        color = 4;  /* white */
    } else if (ch == ')') {
        color = 8;  /* black */
    }
}

/* Main function */
int main(int argc, char *argv[]) {
    int i, j;
    int opt;
    int tty_arg = 0;
    const char *tty = NULL;
    const char *color_arg = NULL;
    const char *message_arg = NULL;
    int delay_arg = 0;

    /* Parse command line arguments */
    while ((opt = getopt(argc, argv, "abBcfhlsmVxknt:u:C:M:")) != -1) {
        switch (opt) {
            case 'a':
                async_scroll = 1;
                break;
            case 'b':
                bold_chars = 1;
                break;
            case 'B':
                all_bold = 1;
                break;
            case 'c':
                shadow_mode = 1;
                use_japanese = 1;
                break;
            case 'f':
