+    } else if (ch == '@') {
+        color = 1;
+    } else if (ch == '#') {
+        color = 5;
+    } else if (ch == '$') {
+        color = 3;
+    } else if (ch == '%') {
+        color = 7;
+    } else if (ch == '^') {
+        color = 6;
+    } else if (ch == '&') {
