    int cols, rows;
    cols = terminal_width();
    rows = terminal_height();

    if (cols <= 0) cols = 80;
    if (rows <= 0) rows = 24;

    draw_screen(cols, rows);

    if (screensaver_mode) {
        struct termios oldt;
        tcgetattr(STDIN_FILENO, &oldt);
        fd_set readfds;
        struct timeval tv;

        while (1) {
            FD_ZERO(&readfds);
            FD_SET(STDIN_FILENO, &readfds);
            tv.tv_sec = 0;
            tv.tv_usec = 100000;

            if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
                char buf[1];
                read(STDIN_FILENO, buf, 1);
                restore_terminal(&oldt);
                break;
            }
        }
    }

    restore_terminal(NULL);

    return 0;
}
